def dollar_to_speech(dollar_string):
    dollars = int(dollar_string[1:]) // 100
    cents = int(dollar_string[1:]) % 100

    def word(d):
        if d == 0:
            return "no"
        elif d == 1:
            return "one"
        elif d == 2:
            return "two"
        elif d == 3:
            return "three"
        elif d == 4:
            return "four"
        elif d == 5:
            return "five"
        elif d == 6:
            return "six"
        elif d == 7:
            return "seven"
        elif d == 8:
            return "eight"
        elif d == 9:
            return "nine"
        elif d < 10:
            return str(d)
        elif d == 10:
            return "ten"
        elif d < 20:
            return str(d)
        elif d < 100:
            tens = d // 10
            if tens == 1:
                return "ten"
            elif tens == 2:
                return "twenty"
            elif tens == 3:
                return "thirty"
            elif tens == 4:
                return "forty"
            elif tens == 5:
                return "fifty"
            elif tens == 6:
                return "sixty"
            elif tens == 7:
                return "seventy"
            elif tens == 8:
                return "eighty"
            elif tens == 9:
                return "ninety"
        else:
            return None

    if dollars < 0:
        return "No negative numbers are allowed!"
    else:
        dollars_str = str(dollars)
        if len(dollars_str) < 2:
            dollars_str = '0' + dollars_str

        dollars_parts = []
        for i, digit in enumerate(dollars_str[::-1]):
            if i == len(dollars_str) - 2 and cents != 0 and int(cents) > 0:
                dollars_parts.append(word(int(digit)) + " hundred and ")
                cents = int(cents)
            else:
                dollars_parts.append(word(int(digit)))
        dollars_parts.append("dollar")
        if cents != 0:
            cents_str = str(cents)
            if len(cents_str) < 2:
                cents_str = '0' + cents_str
            cents_parts = []
            for i, digit in enumerate(cents_str[::-1]):
                if i == 1 and cents != 10 and cents != 100:
                    cents_parts.append(word(int(digit)) + " cent")
                else:
                    cents_parts.append(word(int(digit)))
            cents_parts[-1] = cents_parts[-1][:-1]
            dollars_parts.extend(cents_parts)

        result = "".join(dollars_parts)

        if result.endswith("s"):
            result = result[:-1]
        if result.endswith("cent"):
            result += "s"

        return result + "s" if cents != 0 else result
